import { defineConfig, loadEnv } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), "");
  const apiOrigin = new URL(env.VITE_API_URL || "http://127.0.0.1:5000/api").origin;

  return {
    plugins: [react(), tailwindcss()],
    server: {
      // sitemap.xml and robots.txt are generated by the API but must live on the shop's own
      // address. In production the web server forwards them the same way (see README).
      proxy: {
        "/sitemap.xml": apiOrigin,
        "/robots.txt": apiOrigin,
      },
    },
  };
});
